package com.axsos.Life.models; import jakarta.persistence.*; import java.time.LocalTime; import static com.axsos.Life.models.Enums.*;
@Entity @Table(name="roadmap_items") public class RoadmapItem extends BaseEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="roadmap_id") private Roadmap roadmap; @Enumerated(EnumType.STRING) private RoadmapCategory category; private String slot; private String title; @Column(length=1200) private String description; private LocalTime scheduledTime; private Integer kcal; private Double protein; private Double carbs; private Double fat; private Integer waterAmountMl; private String activityType; private Integer duration; @Enumerated(EnumType.STRING) private RoadmapItemStatus status=RoadmapItemStatus.PENDING; private Integer displayOrder;
 public Long getId(){return id;} public void setId(Long v){id=v;} public Roadmap getRoadmap(){return roadmap;} public void setRoadmap(Roadmap v){roadmap=v;} public RoadmapCategory getCategory(){return category;} public void setCategory(RoadmapCategory v){category=v;} public String getSlot(){return slot;} public void setSlot(String v){slot=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public LocalTime getScheduledTime(){return scheduledTime;} public void setScheduledTime(LocalTime v){scheduledTime=v;} public Integer getKcal(){return kcal;} public void setKcal(Integer v){kcal=v;} public Double getProtein(){return protein;} public void setProtein(Double v){protein=v;} public Double getCarbs(){return carbs;} public void setCarbs(Double v){carbs=v;} public Double getFat(){return fat;} public void setFat(Double v){fat=v;} public Integer getWaterAmountMl(){return waterAmountMl;} public void setWaterAmountMl(Integer v){waterAmountMl=v;} public String getActivityType(){return activityType;} public void setActivityType(String v){activityType=v;} public Integer getDuration(){return duration;} public void setDuration(Integer v){duration=v;} public RoadmapItemStatus getStatus(){return status;} public void setStatus(RoadmapItemStatus v){status=v;} public Integer getDisplayOrder(){return displayOrder;} public void setDisplayOrder(Integer v){displayOrder=v;}
}
